{"packet_id":"D048-01","doc_id":"D048","jurisdiction":"MA","category":"rent_increase_limits","lifecycle":"enacted","title":"Massachusetts ban on local rent control (ch. 40P)","requirement":"No city or town may enact, maintain or enforce rent control of any kind. Only a city or town that accepts this chapter may adopt rent control regulation, and owner compliance becomes entirely voluntary and uncoerced six months after initial adoption.","key_value":"10 rental units; $400 fair market rent; voluntary after 6 months","coverage_conditions":"All Massachusetts cities and towns. Rent control may be adopted only by a municipality accepting this chapter, and may not apply to units of owners holding fewer than ten rental units or with fair market rent above $400.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Municipal rent control only where the city or town accepts chapter 40P"},"exemptions":"Regulation may not apply to any rental unit owned by a person or entity owning fewer than ten rental units, or to a unit with fair market rent exceeding $400.","penalty":null,"effective_date":null,"citation":"G.L. c. 40P, § 4","quoted_span":"No city or town may enact, maintain or enforce rent control of any kind, except that any city or town that accepts this chapter may adopt rent control regulation that provides:","interaction":"State law bars local rent control unless the municipality accepts chapter 40P and conforms to its conditions.","confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D048-01","doc_id":"D048","jurisdiction":"MA","category":"just_cause_eviction","lifecycle":"enacted","title":"Chapter 40P limit on local eviction regulation","requirement":"Rent control regulation adopted by a city or town under chapter 40P may not include the regulation of evictions, occupancy, services, condominium conversion or the removal of properties from such regulation.","key_value":null,"coverage_conditions":"Municipal rent control regulation adopted by a city or town that accepts chapter 40P, and only as to units subject to that regulation.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Applies to municipal rent control regulation under chapter 40P"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"G.L. c. 40P, § 4","quoted_span":"such regulation may not include the regulation of occupancy, services, evictions, condominium conversion or the removal of properties from such regulation","interaction":"Limits what a municipality accepting chapter 40P may regulate; local eviction regulation is excluded.","confidence":0.65,"conflict_flag":false,"conflict_note":null}
